בהנחה שהמחלקה `Deep` הבאה מוגדרת כך, מה מדפיסה התכנית?
```cpp
struct Deep {
    int* p;
    Deep(int v) : p(new int(v)) {}
    Deep(const Deep& o) : p(new int(*o.p)) {}
    Deep& operator=(const Deep& o) {
        if (this != &o) { delete p; p = new int(*o.p); }
        return *this;
    }
    ~Deep() { delete p; }
};
int main() {
    Deep a(5);
    Deep b = a;
    *b.p = 9;
    cout << *a.p << *b.p;
}
```

