בהנחה שהמחלקה `Deep` הבאה מוגדרת כך, מה מדפיסה התכנית? (`allocs` סופר כמה בלוקים הוקצו.)
```cpp
struct Deep {
    static int allocs;
    int* p;
    Deep(int v) : p(new int(v)) { allocs++; }
    Deep(const Deep& o) : p(new int(*o.p)) { allocs++; }
    Deep& operator=(const Deep& o) {
        if (this != &o) { delete p; p = new int(*o.p); allocs++; }
        return *this;
    }
    ~Deep() { delete p; }
};
int Deep::allocs = 0;
int main() {
    Deep a(1);
    Deep b = a;
    Deep c(2);
    c = a;
    cout << Deep::allocs;
}
```

